class Solution {
    public int canCompleteCircuit(int[] gas, int[] cost) {
        int totalCost = 0;
        int totalGas = 0;
        int currentTank = 0;
        int start = 0;
        for(int i=0; i<gas.length; i++){
            totalCost += cost[i];
            totalGas += gas[i];
            currentTank += gas[i]-cost[i];
            if(currentTank<0){
                currentTank = 0;
                start = i+1;
            }
        }
        return totalGas >= totalCost ? start : -1;
    }
}
